-- taskProjectService: Legacy column additions for databases created before dataMigrate
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'project_repos' AND COLUMN_NAME = 'clone_alias') = 0, 'ALTER TABLE project_repos ADD COLUMN clone_alias VARCHAR(255) NOT NULL DEFAULT ''''', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'project_workspace_entries' AND COLUMN_NAME = 'container_image_at_mode_enabled') = 0, 'ALTER TABLE project_workspace_entries ADD COLUMN container_image_at_mode_enabled TINYINT NOT NULL DEFAULT 1', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
